        string memory newSymbol = c.symbol();
        string memory newName = c.name();
        uint256 newDecimals = c.decimals();

        assert(
            keccak256(abi.encodePacked(newSymbol)) == keccak256(abi.encodePacked(initialSymbol)) &&
            bytes(newSymbol).length > 0 &&
            keccak256(abi.encodePacked(newName)) == keccak256(abi.encodePacked(initialName)) &&
            bytes(newName).length > 0 &&
            newDecimals == initialDecimals
        );
    }

    receive() external payable {}
}

