contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "recipient is zero");

        uint256 rBefore = c.balanceOf(recipient);
        uint256 sBefore = c.balanceOf(address(this));

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 rAfter = c.balanceOf(recipient);
        uint256 sAfter = c.balanceOf(address(this));

        if (reverted) {
            assert(rAfter == rBefore && sAfter == sBefore);
        } else {
            assert(rAfter == rBefore + amount && sAfter == sBefore - amount);
        }
    }
}

