contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address owner, address spender, uint256 amount, bool useApprove, bool useTransferFrom) public {
        require(owner != address(0));
        require(spender != address(0));

        uint256 before = c.allowance(owner, spender);

        bool reverted;
        if (useApprove) {
            try c.approve(spender, amount) { reverted = false; } catch { reverted = true; }
            if (!reverted) {
                uint256 afterApprove = c.allowance(owner, spender);
                assert(afterApprove == amount);
            } else {
                uint256 afterApproveFail = c.allowance(owner, spender);
                assert(afterApproveFail == before);
            }
        } else if (useTransferFrom) {
            try c.transferFrom(owner, spender, amount) { reverted = false; } catch { reverted = true; }
            if (!reverted) {
                // transferFrom subtracts amount from owner's allowance to spender
                assert(c.allowance(owner, spender) <= before);
            } else {
                assert(c.allowance(owner, spender) == before);
            }
        } else {
            // No state-changing call made: allowance must be unchanged
            assert(c.allowance(owner, spender) == before);
        }
    }

    receive() external payable {}
}

