    constructor(C _c) { c = _c; }

    function run(address spender, uint256 addedValue, uint256 subtractedValue) public {
        require(spender != address(0), "spender zero");
        c.approve(spender, addedValue);
        uint256 beforeAllowance = c.allowance(address(this), spender);
        bool reverted;
        try c.decreaseAllowance(spender, subtractedValue) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            uint256 afterAllowance = c.allowance(address(this), spender);
            assert(afterAllowance == beforeAllowance - subtractedValue);
        } else {
            uint256 afterAllowance = c.allowance(address(this), spender);
            assert(afterAllowance == beforeAllowance);
        }
    }
}

