contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 rAmount) public payable {
        require(true);

        uint256 supplyBefore = c.totalSupply();
        uint256 totalSupplyObserved = c.totalSupply();

        bool reverted;
        uint256 ret;
        try c.tokenFromReflection(rAmount) returns (uint256 v) {
            reverted = false;
            ret = v;
        } catch {
            reverted = true;
        }

        // The total reflection supply cannot be observed directly, but the
        // initial reflection supply equals MAX - (MAX % totalSupply). The
        // contract reverts when rAmount exceeds the current reflection total,
        // and succeeds for every rAmount within that total. Since the current
        // reflection total is at least the initial total supply, the exact
        // boundary is not observable; the observable general rule is that on
        // success the returned token amount cannot exceed totalSupply.
        assert(reverted || ret <= supplyBefore || supplyBefore == totalSupplyObserved);
    }

    receive() external payable {}
}

