        uint256 actual;
        try c.tokenFromReflection(rAmount) returns (uint256 v) {
            actual = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        // If not reverted, the returned amount must be rAmount divided by the current rate.
        // The rate is rTotal / tTotal, where rTotal = MAX - (MAX % tTotal) initially,
        // and totalSupply is observable through c.totalSupply().
        // We compute the expected result using the same formula the contract uses:
        // currentRate = rSupply / tSupply, and with an initially undistributed state
        // rSupply = rTotal, tSupply = tTotal.
        uint256 max = ~uint256(0);
        uint256 tTotal = c.totalSupply();
        uint256 rTotal = max - (max % tTotal);
        uint256 rate = rTotal / tTotal;
        uint256 expected = rAmount / rate;

        if (!reverted) {
            assert(actual == expected);
        } else {
            // If it reverted, the input must have been greater than the total reflections.
            assert(rAmount > rTotal);
        }
    }
}

