contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "zero recipient");
        require(amount > 0, "zero amount");

        // Ensure this test contract is an allowed sender.
        // owner is the deployer (this contract), so calls originate here.
        // Read observable state before the transfer.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 recipBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();

        // Top-level state-changing call; capture its return value and revert flag.
        bool transferOk = false;
        bool transferReverted = false;
        try c.transfer(recipient, amount) returns (bool ok) {
            transferOk = ok;
        } catch {
            transferReverted = true;
        }

        // Observable state after the call.
        uint256 balAfter = c.balanceOf(address(this));
        uint256 recipAfter = c.balanceOf(recipient);
        uint256 supplyAfter = c.totalSupply();

        // General rule: if the call does not revert, it must return true.
        // Also the total token supply must be unchanged by a transfer.
        assert(transferReverted || (transferOk && supplyAfter == supplyBefore));
    }

    receive() external payable {}
}

