            tAmount = v;
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            uint256 totalSupply = c.totalSupply();
            uint256 currentRate = (0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff - (0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff % totalSupply)) / totalSupply;
            assert(tAmount == rAmount / currentRate);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

